import{_ as a,o as r,c as t,ag as i}from"./chunks/framework.Cu2CLAe3.js";const u=JSON.parse('{"title":"智能指针与 RAII","description":"用 RAII 和智能指针实现自动资源管理","frontmatter":{"title":"智能指针与 RAII","description":"用 RAII 和智能指针实现自动资源管理"},"headers":[],"relativePath":"vol2-modern-features/ch01-smart-pointers/index.md","filePath":"vol2-modern-features/ch01-smart-pointers/index.md","lastUpdated":null}'),o={name:"vol2-modern-features/ch01-smart-pointers/index.md"};function l(n,e,s,d,p,_){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="智能指针与-raii" tabindex="-1">智能指针与 RAII <a class="header-anchor" href="#智能指针与-raii" aria-label="Permalink to &quot;智能指针与 RAII&quot;">​</a></h1><p>手动管理资源（new/delete、fopen/fclose、lock/unlock）是 C++ 程序员的噩梦之源。RAII 原则告诉我们：把资源的获取绑定到对象的构造，释放交给析构，让作用域替你管理生命周期。这一章我们先深入理解 RAII，然后逐一掌握 unique_ptr、shared_ptr、weak_ptr 的设计哲学和正确用法，最后看看自定义删除器和 scope_guard 怎么处理更复杂的资源场景。</p><h2 id="本章内容" tabindex="-1">本章内容 <a class="header-anchor" href="#本章内容" aria-label="Permalink to &quot;本章内容&quot;">​</a></h2><ul><li><a href="./01-raii-deep-dive">RAII 深入理解：资源管理的基石</a></li><li><a href="./02-unique-ptr">unique_ptr 详解：独占所有权的零开销智能指针</a></li><li><a href="./03-shared-ptr">shared_ptr 详解：共享所有权与引用计数</a></li><li><a href="./04-weak-ptr">weak_ptr 与循环引用</a></li><li><a href="./05-custom-deleter">自定义删除器与侵入式引用计数</a></li><li><a href="./06-scope-guard">scope_guard 与 defer：通用作用域守卫</a></li></ul>',4)])])}const h=a(o,[["render",l]]);export{u as __pageData,h as default};
